CREATE TABLE IF NOT EXISTS library_books (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), isbn TEXT, title TEXT NOT NULL, authors_json TEXT, category TEXT, shelf TEXT, copies INTEGER NOT NULL, available_copies INTEGER NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS library_loans (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), book_id TEXT NOT NULL REFERENCES library_books(id), borrower_id TEXT NOT NULL, borrower_type TEXT NOT NULL, due_at TEXT, status TEXT NOT NULL, borrowed_by TEXT NOT NULL REFERENCES users(id), borrowed_at TEXT NOT NULL, returned_at TEXT);
CREATE TABLE IF NOT EXISTS transport_vehicles (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), registration TEXT NOT NULL, insurance_expires_at TEXT, roadworthiness_expires_at TEXT, driver_id TEXT, attendant_ids_json TEXT, emergency_contact TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(school_id, registration));
CREATE TABLE IF NOT EXISTS transport_routes (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, stops_json TEXT, vehicle_id TEXT REFERENCES transport_vehicles(id), student_ids_json TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hostel_spaces (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), type TEXT NOT NULL, name TEXT NOT NULL, capacity INTEGER NOT NULL, warden_id TEXT, matron_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS hostel_allocations (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), space_id TEXT NOT NULL REFERENCES hostel_spaces(id), bed TEXT, active INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS health_records (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), data_json TEXT NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS health_visits (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), data_json TEXT NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS welfare_incidents (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), kind TEXT NOT NULL, data_json TEXT NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS counselling_records (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), student_id TEXT NOT NULL REFERENCES student_profiles(id), data_json TEXT NOT NULL, recorded_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_operations_student ON health_records(school_id, student_id);
CREATE INDEX IF NOT EXISTS idx_welfare_student ON welfare_incidents(school_id, student_id);
